files.browser-use/references/signin-rules.json:
{
 "format": 1,
 "about": "Site sign-in rules the host runs as data (Gurumi SignInAgent + SigninRules). Each rule: the sites it covers, a one-line note for the sign-in head, the ways to offer (only these), each way's session page ({return} = the address to come back to once signed in) and the words of the control that starts it on that page. A way with requires_app is offered only when that app is on the phone.",
 "rules": [
  {
   "id": "naver",
   "sites": ["naver.com"],
   "note": "NAVER (naver.com and every NAVER service, and \"Sign in with NAVER\" on other sites): in this in-app browser the ID and password and the passkey do not work -- never type them and never list them as ways. Sign in only with the QR code or, when the NAVER app is on this phone, with the NAVER app (its \"앱 열기\" / \"Open app\" control). Once signed in, go back to the original sign-in.",
   "return_param": "url",
   "ways": [
    {
     "id": "qr",
     "kind": "qr",
     "name": {"ko": "QR 코드", "en": "a QR code"},
     "page": "https://nid.naver.com/nidlogin.login?mode=form&url={return}",
     "press": ["QR 코드 로그인", "QR sign-in"]
    },
    {
     "id": "app",
     "kind": "app",
     "name": {"ko": "네이버 앱", "en": "the NAVER app"},
     "page": "https://nid.naver.com/nidlogin.login?mode=form&svctype=262144&url={return}",
     "press": ["앱 열기", "Open app"],
     "requires_app": "com.nhn.android.search"
    }
   ]
  }
 ]
}
